#' Plot fully differenced transformed series for the original series, seasonal adjustment, and trend 
#' from an X-13ARIMA-SEATS SEATS seasonal adjustment run. 
#'
#' Generate plot of the fully differenced transformed series from a SEATS adjustment
#' from a \code{seas} object generated by the \code{seasonal} package. 
#' 
#' Version 2.7, 2026-09-30
#'
#' @param seas_obj \code{seas} object for a single series generated by the
#'        \code{seasonal} package \insertCite{seasonal2018}{blsplotGG}.
#'        This is a required entry.
#' @param overall_title Character string; main title of plot. 
#'        A title will be generated if no title is specified. If \code{this_series = "all"},
#'        this title will be the overall plot title and descriptive text will be added.
#' @param this_y_label Character string; y-axis label for plot, if specified.
#' @param y_limit Numeric vector of length 2; 
#'        Range of values you wish the plot to be plotted over. 
#'        Default is range of the series specified.
#' @param this_x_label Label for X axis. Default is \code{"Time"}; not displayed if \code{this_series = "all"}.
#' @param start_plot Integer vector of length 2; Starting date for plot. 
#'        Default is starting date for the time series. 
#' @param do_grid Logical scalar; indicates if certain plots will have grid lines.
#'        Default is no grid lines. 
#' @param do_background Logical scalar; indicates grey background included in plot.
#'        Default is no grey background;
#' @param draw_recess Logical scalar; indicates if certain plots will have 
#'        shaded areas for NBER recession dates. 
#'        Default is no recession shading. 
#' @param recess_color Character string; color used for shading of recession region. 
#'        Default is \code{"lightgrey"}. For a listing of R color codes, 
#'        see \insertCite{rchartsColors;textual}{blsplotGG}.
#' @param recess_sub Logical scalar; indicates if x-axis label for recession is 
#'        produced for this plot. 
#'        Default is x-axis label.
#' @param title_size integer scalar; Size of the plot title. 
#'        If \code{this_series = "all"}, the overall title size will be \code{title_size} + 2.
#'        Default is \code{10}.
#' @param add_zero_line Logical scalar; if TRUE, adds a grey zero line to plots. 
#'        Default is FALSE, no zero line is added.
#' @param line_color Character string; color used for series in the plot.  
#'        Default is \code{"steelblue"}. For a listing of R color codes, 
#'        see \insertCite{rchartsColors;textual}{blsplotGG}.
#' @return A \code{ggplot} object that generates a plot of the fully differenced transformed series 
#'         from a SEATS seasonal adjustment. If SEATS seasonal adjustment not produced, 
#'         print out error message and return \code{NULL}.
#'
#' @author Brian C. Monsell, \email{monsell.brian@@bls.gov} or \email{bcmonsell@@gmail.com}
#'
#' @references
#'  \insertAllCited{}
#'
#' @examples
#' shoes_seats_seas <- 
#'    seasonal::seas(shoes2008, arima.model = "(0 1 1)(0 1 1)", 
#'                   transform.function = "log", 
#'                   forecast.maxlead = 36,
#'                   check.print = c( 'pacf', 'pacfplot' ), 
#'                   seats.finite = "yes",
#'                   seats.save = c( 'dor', 'dsa', 'dtr' ) )
#' p_all_full_diff <- 
#'  plot_fully_differenced_transformed_all(shoes_seats_seas,
#'   overall_title = "US Shoe Sales",
#'   title_size = 8,
#'   add_zero_line = TRUE,
#'   line_color = "darkgreen")
#' @importFrom Rdpack reprompt
#' @export
plot_fully_differenced_transformed_all <- function(
	seas_obj = NULL, 
	overall_title = NULL, 
	this_y_label = NULL, 
	y_limit = NULL, 
	this_x_label = "Time", 
	start_plot = NULL, 
	do_grid = FALSE, 
	do_background = FALSE, 
	draw_recess = FALSE, 
	recess_color = "lightgrey", 
	recess_sub = TRUE,
	title_size = 10,
	add_zero_line = FALSE,
	line_color = "steelblue") {
    # Author: Brian C. Monsell (OEUS) Version 2.7, 2026-09-30
	
    # check if a value is specified for \code{seas_obj}
    if (is.null(seas_obj)) {
        cat("must specify a seas object")
		return(NULL)
    } else {
    # check if a seas object is specified for \code{seas_obj}
        if (!inherits(seas_obj, "seas")) {
            cat("First argument must be a seas object")
			return(NULL)
        }
    }
	
	if (!("seatsadj" %in% names(seasonal::udg(seas_obj)))) {
		cat("Must use SEATS to generate seasonal adjustment")
		return(NULL)
	}
    
	this_log <- FALSE
	if (seasonal::udg(seas_obj, "transform") == "Log(y)") {
		this_log <- TRUE
	}
	
    # check if value of \code{title_size} is valid, return \code{NULL} if not.
	if (title_size <= 0) {
        cat(paste("Title size not valid (must be greater than zero):", 
		           title_size))
        return(NULL)
	}
	
	dor <- seasonal::series(seas_obj, "dor")
	dsa <- seasonal::series(seas_obj, "dsa")
	dtr <- seasonal::series(seas_obj, "dtr")
	
	x_limit <- 
		range(tsbox::ts_df(dor)$time, tsbox::ts_df(dsa)$time, tsbox::ts_df(dtr)$time)
	
	panel_title <- "Original Series"
		
	p_list <- list()
		
	p_list[["p1"]] <- 
		plot_table(seas_obj, 
		           "dor",
		           panel_title, 
		           NULL,
				   FALSE,
		           this_y_label,
		           y_limit, 
		           NULL,
		           start_plot, 
		           do_grid, 
		           do_background,
		           draw_recess,
		           recess_color,
		           recess_sub,
		           add_outlier = FALSE, 
		           use_ratio = FALSE, 
				   this_line_type = "solid", 
		           line_color = line_color) + 
		ggplot2::theme(plot.title = ggplot2::element_text(size = title_size), 
		               axis.text.x = ggplot2::element_text(size = title_size))+
		ggplot2::coord_cartesian(xlim = x_limit)
		
	if (add_zero_line) { 
		p_list[["p1"]] <- p_list[["p1"]] +
			ggplot2::geom_hline(yintercept = 0.0, color = "lightgrey")
	}
		
	panel_title <- "SEATS Seasonal Adjustment"
		
	p_list[["p2"]] <- 
	  plot_table(seas_obj, 
	             "dsa", 
	             panel_title, 
	             NULL,
				 FALSE,
	             this_y_label, 
	             y_limit, 
	             NULL,
	             start_plot, 
	             do_grid, 
	             do_background,
	             draw_recess,
	             recess_color,
	             recess_sub,
	             add_outlier = FALSE, 
	             use_ratio = FALSE, 
	             this_line_type = "solid", 
	             line_color = line_color) + 
		ggplot2::theme(plot.title = ggplot2::element_text(size = title_size), 
		               axis.text.x = ggplot2::element_text(size = title_size)) +
		ggplot2::coord_cartesian(xlim = x_limit)
	
	if (add_zero_line) { 
		p_list[["p2"]] <- p_list[["p2"]] +
			ggplot2::geom_hline(yintercept = 0.0, color = "lightgrey")
	}
		
	panel_title <- "SEATS Trend"
		
	p_list[["p3"]] <- 
		plot_table(seas_obj, 
				   "dtr",
				   panel_title, 
				   NULL,
				   FALSE,
				   this_y_label,
				   y_limit, 
				   NULL,
				   start_plot, 
				   do_grid, 
				   do_background,
				   draw_recess,
				   recess_color,
				   recess_sub,
				   add_outlier = FALSE, 
				   use_ratio = FALSE, 
				   this_line_type = "solid", 
				   line_color = line_color) + 
		ggplot2::theme(plot.title = ggplot2::element_text(size = title_size), 
		               axis.text.x = ggplot2::element_text(size = title_size)) +
		ggplot2::coord_cartesian(xlim = x_limit)
	
	if (add_zero_line) { 
		p_list[["p3"]] <- p_list[["p3"]] +
			ggplot2::geom_hline(yintercept = 0.0, color = "lightgrey")
	}
		
	p_final <- 
		ggpubr::ggarrange(plotlist = p_list, 
			nrow = 3, 
			ncol = 1)

	if (is.null(overall_title)) {
		overall_title <- "Fully Differenced "
		if (this_log) {
			overall_title <- paste0(overall_title, "Log Transformed ")
		}
		overall_title <- paste0(overall_title, "Series Plot")
	}
	p_final <- ggpubr::annotate_figure(p_final, 
		top = ggpubr::text_grob(overall_title, size = title_size + 2))
		
	return(p_final)
	
}
			